// Bun.file(path).writer(): flush() and end() settle once what was written is in the file, so
// a reader after `await end()` (ffmpeg muxing downloaded segments) sees all of it.
import { file } from "bun";
import { statSync, readFileSync, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

export default async function run() {
  const dir = mkdtempSync(join(tmpdir(), "tov-writer-"));
  const chunk = new Uint8Array(64 * 1024).fill(7);
  const sizes = await Promise.all(Array.from({ length: 16 }, async (_, i) => {
    const path = join(dir, `f${i}`);
    const w = file(path).writer();
    for (let k = 0; k < 40; k++) {
      w.write(chunk);
      await w.flush();
    }
    w.write("tail");
    await w.end();
    return statSync(path).size;
  }));
  const want = 40 * chunk.length + 4;
  console.log("every file whole at end:", sizes.every((size) => size === want));
  console.log("last bytes:", readFileSync(join(dir, "f0")).subarray(-4).toString());
}
